class BillingPublishableKeys(Resource):
    """Publishable keys (``pk_...``): what a web page reads the public catalog with.

    A publishable key is not a secret: it ships in pages, and a browser may send it only from
    one of its allowed origins. With ``anonymous_checkout``, it also starts checkouts for
    visitors your backend does not know yet.
    """

    def list(self, *, include_revoked: bool = False) -> builtins.list[PublishableKey]:
        """Return the organization's keys, newest first: their last characters, never the keys."""
        return self._api.list_all(
            "/publishable-keys", PublishableKey, params={"includeRevoked": include_revoked or None}
        )

    def create(
        self,
        *,
        label: str,
        allowed_origins: Sequence[str],
        anonymous_checkout: bool | None = None,
        turnstile_site_key: str | None = None,
        turnstile_secret: str | None = None,
    ) -> PublishableKeyCreated:
        """Issue a publishable key, and return it with the key, which exists in this response only.

        Args:
            label: What the key is for.
            allowed_origins: The browser origins allowed to send it, as
                ``scheme://host[:port]``: https, or http on localhost. Empty, no browser may;
                a request without an ``Origin`` header -- server-side rendering -- still may.
            anonymous_checkout: Let the key start anonymous checkouts. It needs a Turnstile site
                key and secret.
            turnstile_site_key: The Turnstile site key the page renders its widget with.
            turnstile_secret: The Turnstile secret the server verifies tokens with, kept in
                Vault and never returned.
        """
        body = {
            "label": label,
            "allowedOrigins": list(allowed_origins),
            **compact(
                {
                    "anonymousCheckout": anonymous_checkout,
                    "turnstileSiteKey": turnstile_site_key,
                    "turnstileSecret": turnstile_secret,
                }
            ),
        }
        return self._api.send("POST", "/publishable-keys", PublishableKeyCreated, body=body)

    def update(
        self,
        key_id: str,
        *,
        label: str | None = None,
        allowed_origins: Sequence[str] | None = None,
        anonymous_checkout: bool | None = None,
        turnstile_site_key: str | None = None,
        turnstile_secret: str | None = None,
    ) -> PublishableKey:
        """Change a live key; what is omitted keeps its value, and ``""`` clears a Turnstile value.

        Raises:
            ConflictError: The key is revoked (``UpdatePublishableKey.Revoked``).
        """
        body = compact(
            {
                "label": label,
                "allowedOrigins": list(allowed_origins) if allowed_origins is not None else None,
                "anonymousCheckout": anonymous_checkout,
                "turnstileSiteKey": turnstile_site_key,
                "turnstileSecret": turnstile_secret,
            }
        )
        return self._api.send(
            "PATCH", api_path("publishable-keys", key_id), PublishableKey, body=body
        )

    def revoke(self, key_id: str) -> PublishableKey:
        """Revoke a key, for good, with its anonymous checkout sessions. Idempotent."""
        return self._api.send(
            "POST", api_path("publishable-keys", key_id, "revoke"), PublishableKey, idempotent=True
        )


class BillingCustomerSessions(Resource):
    """Customer sessions (``kst_...``): what lets a customer's browser act on its own billing.

    Mint one from your backend, where the customer is signed in, and hand its token to the
    page, which calls the routes of :attr:`Billing.session` with it.
    """

    def create(
        self,
        *,
        customer_slug: str,
        instance_slug: str | None = None,
        ttl_seconds: int | None = None,
    ) -> CreatedCustomerSession:
        """Mint a session for a customer, and return it with its token, shown this once.

        What the session writes is attributed to the credential that minted it.

        Args:
            customer_slug: The customer the session acts for.
            instance_slug: Bind it to one of the customer's instances, which checkout, cancel
                and the other subscription routes need.
            ttl_seconds: How long it lives, 300 to 3600 seconds. 30 minutes when omitted.
        """
        body = {
            "customerSlug": customer_slug,
            **compact({"instanceSlug": instance_slug, "ttlSeconds": ttl_seconds}),
        }
        return self._api.send("POST", "/customer-sessions", CreatedCustomerSession, body=body)

    def revoke(self, session_id: str) -> None:
        """Stop a session authenticating, from its next request: on sign-out, say. Idempotent."""
        self._api.send_empty(
            "POST", api_path("customer-sessions", session_id, "revoke"), idempotent=True
        )


class BillingCheckoutSessions(Resource):
    """Anonymous checkouts, as the organization reads them: never their token or voucher code.

    It is how a buyer is linked to your own account when the ``checkout_session`` events were
    missed.
    """

    def list(
        self,
        *,
        status: Sequence[CheckoutSessionStatus] | None = None,
        email: str | None = None,
        client_reference_id: str | None = None,
        limit: int | None = None,
    ) -> builtins.list[CheckoutSessionAdmin]:
        """Return the organization's anonymous checkouts, newest first.

        Args:
            status: Only sessions in these statuses. A session ``OPEN`` past its expiry is
                ``ABANDONED``.
            email: Only the visitor with this e-mail, in any letter case.
            client_reference_id: Only the sessions started with this reference of yours.
            limit: The most sessions to return. Every page is walked when omitted.
        """
        return self._api.list_all(
            "/checkout-sessions",
            CheckoutSessionAdmin,
            params={
                "status": list(status) if status is not None else None,
                "email": email,
                "clientReferenceId": client_reference_id,
            },
            limit=check_limit(limit),
        )

    def get(self, session_id: str) -> CheckoutSessionAdmin:
        """Return an anonymous checkout. One closed 90 days ago is gone."""
        return self._api.get(api_path("checkout-sessions", session_id), CheckoutSessionAdmin)
